import { Component, h, Host, Prop, State, Event, Element, EventEmitter, Watch, VNode } from '@stencil/core';
import { Slot, Slots, Vue2ValueFix } from '@src/framework/decorators';
import { commonMessages, searchMessages } from '@fe-infra/keystone-locales';
import { t } from '@src/shared/i18n';
import { DetailArgs } from '@src/shared/dom';
import { Value } from '@src/components/ks-value-field/types';
import { RenderConfig } from '@src/components/ks-virtual-list/types';
import { KsVirtualList } from '@src/components/ks-virtual-list';
import { flattenDropdownData } from './utils/flattenDropdownData';
import { FlattenNode } from '@src/components/ks-tree-view/utils';
import { KsDropdownItem } from '@src/components/ks-menu-item/dropdown-item';
import { renderDynamicChildren, renderItemSlots, renderPassThroughSlots } from '@src/components/ks-menu-item/utils';
import { noop } from 'lodash-es';
import { DropdownItem } from './types';

const DEFAULT_HEIGHT = 36;
const DEFAULT_HEIGHT_WITH_DESC = 54;

const prefix = 'dropdown-menu__list';

/**
 * @slot listHeader - Slot for custom header at the top of the list (scrollable area in DropdownMenu).
 * @slot empty - Slot for custom content when the list is empty.
 * @slot loadFailure - Slot for custom content when the list fails to load.
 * @slot loadMoreFailure - Slot for custom content when the list fails to load more items.
 */
@Component({
  tag: 'ks-dropdown-menu-list',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsDropdownMenuList extends KsVirtualList<FlattenNode<DropdownItem>> {
  @Element() override el!: HTMLKsDropdownMenuListElement;

  protected override prefixCls = prefix;
  protected override items: FlattenNode<DropdownItem>[] = [];
  protected override renderItem(item: FlattenNode<DropdownItem>, index: number): VNode {
    const { data } = item;
    const { value: key } = data;

    // merged states for render
    const mergedMultiple = this.multiple || data.multiple || false;
    const mergedChecked = this.value?.includes(key) || data.checked || false;
    const mergedHalfChecked = this.halfValues?.includes(key) || data.halfChecked || false;
    const mergedDisabled = data.disabled || this.disabled;
    const mergedSelectable = data.selectable;

    const isGroup = Array.isArray(data.children);
    const mergedShowDivider = Object.is(item, this.items[0]) ? false : !this.hideGroupDivider && isGroup;

    return (
      <KsDropdownItem
        {...data}
        multiple={mergedMultiple}
        value={key}
        checked={mergedChecked}
        indeterminate={mergedHalfChecked}
        disabled={mergedDisabled}
        selectable={mergedSelectable}
        label={typeof data.label === 'string' ? data.label : undefined}
        description={typeof data.description === 'string' ? data.description : undefined}
        helpContent={typeof data.helpContent === 'string' ? data.helpContent : undefined}
        popover={data.popover}
        onClick={(key, event) => {
          event.preventDefault();
          data.onClick?.(key, event);
          this.handleItemClick(key);
        }}
        highlight={(data as DropdownItem & { highlight?: DropdownItem['highlight'] }).highlight || null}
        groupTitle={isGroup}
        showDivider={mergedShowDivider}
        hideCheckmark={data.hideCheckmark}
        dataAttrs={data.dataAttrs}
      >
        {renderItemSlots(data, index)}
      </KsDropdownItem>
    );
  }
  protected override renderDynamicChildrenForItem(
    item: FlattenNode<DropdownItem>,
    index: number,
    wrapWithSlot: (slotName: string, children: unknown) => unknown,
    renderConfig?: RenderConfig,
  ): unknown[] {
    return renderDynamicChildren(item.data, index, wrapWithSlot, renderConfig);
  }
  protected override getPassThroughSlots = (item: FlattenNode<DropdownItem>, index: number) =>
    renderPassThroughSlots(item.data, index);
  protected override DEFAULT_HEIGHT = (item: FlattenNode<DropdownItem>) => {
    const { data } = item;
    return data.description ? DEFAULT_HEIGHT_WITH_DESC : DEFAULT_HEIGHT;
  };

  /** The list of items to be displayed. */
  @Prop() options: DropdownItem[] = [];

  /** A function to filter the options. */
  @Prop() filterOption?: (node: DropdownItem) => boolean;
  /** A function to sort the options. */
  @Prop() sortOption?: (a: DropdownItem, b: DropdownItem) => number;
  /** The search value of the dropdown menu list. */
  @Prop() searchValue?: string;
  @State() filteredOptions?: DropdownItem[];
  @Watch('options')
  @Watch('filterOption')
  @Watch('searchValue')
  generateFilteredOptions() {
    const { filterOption, searchValue, sortOption } = this;
    const options = Array.isArray(this.options) ? this.options : [];

    if (!filterOption) {
      this.filteredOptions = options;
      return;
    }

    const filterOptions = (items: DropdownItem[] = [], keepAll = false): DropdownItem[] =>
      (Array.isArray(items) ? items : []).reduce<DropdownItem[]>((filtered, item) => {
        const isMatch = keepAll || filterOption(item);
        const filteredChildren = Array.isArray(item.children) ? filterOptions(item.children || [], isMatch) : null;

        let highlight: [number, number] | undefined;
        if (typeof item.label === 'string' && typeof searchValue === 'string') {
          const idx = item.label.toLocaleLowerCase().indexOf(searchValue.toLocaleLowerCase());
          if (idx !== -1) {
            highlight = [idx, idx + searchValue.length];
          }
        }

        if (isMatch || filteredChildren?.length) {
          const itemToPush = {
            ...item,
            ['highlight']: highlight,
          };
          if (Array.isArray(filteredChildren)) {
            itemToPush.children = filteredChildren;
          }
          filtered.push(itemToPush);
        }
        return filtered;
      }, []);

    this.filteredOptions = sortOption ? filterOptions(options).sort(sortOption) : filterOptions(options);
  }

  /** Whether to enable virtualization. */
  @Prop() virtual?: boolean | { estimatedItemHeight: number | ((item: FlattenNode<DropdownItem>) => number) };

  /** Indicates whether the dropdown menu list is loading. */
  @Prop() loading?: boolean;

  /** Indicates whether the dropdown menu list is loading more items. */
  @Prop() loadingMore?: boolean;

  /** Indicates whether the dropdown menu list failed to load. */
  @Prop() loadFailed?: boolean;

  /** Indicates whether the dropdown menu list failed to load more items. */
  @Prop() loadMoreFailed?: boolean;

  /** Whether to support selectable items. */
  @Prop() selectable = true;

  /** Whether to support multiple selection. */
  @Prop() multiple = false;

  /** Indicates whether the dropdown menu list is disabled. */
  @Prop() disabled?: boolean;

  /** The selected value(s) of the dropdown menu list. */
  @Prop() @Vue2ValueFix() value?: Value[];

  /** The half selected value(s) of the dropdown menu list. */
  @Prop() halfValues?: Value[];

  /** Whether to hide the divider between groups of items. */
  @Prop() hideGroupDivider = false;

  /** Whether to hide the title of the search result. */
  @Prop() hideSearchResultTitle = false;

  /** The slot at the top of the list (scrollable area in DropdownMenu). */
  @Slot({ slotname: 'listHeader' }) private listHeaderSlots?: Slots;

  /** The slot to be displayed when the list is empty. */
  // @Slot({ slotname: 'empty' }) private emptySlot?: Slots;

  /** The slot to be displayed when the list fails to load. */
  // @Slot({ slotname: 'loadFailure' }) private loadFailureSlot?: Slots;

  /** The slot to be displayed when the list fails to load more items. */
  // @Slot({ slotname: 'loadMoreFailure' }) private loadMoreFailureSlot?: Slots;

  /** Triggered when the value of the dropdown menu list changes. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<
    DetailArgs<
      [
        Value[],
        {
          value: Value;
        },
      ]
    >
  >;

  private handleItemClick(value: Value) {
    if (this.multiple) {
      const nextValue = this.value?.includes(value)
        ? this.value.filter((v) => v !== value)
        : [...(this.value || []), value];
      this.ksChange.emit(DetailArgs(nextValue, { value }));
    } else {
      this.ksChange.emit(DetailArgs([value], { value }));
    }
  }

  @Watch('filteredOptions')
  handleFilteredOptionsChange() {
    this.items = flattenDropdownData(this.filteredOptions || [], true);
  }

  override connectedCallback(): void {
    super.connectedCallback?.();
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback?.();
  }

  override componentWillLoad(): Promise<void> | void {
    this.generateFilteredOptions();
    this.handleFilteredOptionsChange();
    super.componentWillLoad();
  }

  override componentDidRender(): void {
    super.componentDidRender();
  }

  private renderEmpty() {
    return (
      <div key="empty" class={`${this.prefixCls}__empty-or-failed`} data-testid="ks-dropdown-menu-list-index-uHh2pc">
        <slot name="empty">
          <ks-empty-state size="sm" title={t(commonMessages.empty)} />
        </slot>
      </div>
    );
  }

  private renderLoadFail() {
    return (
      <div key="loadFail" class={`${this.prefixCls}__empty-or-failed`} data-testid="ks-dropdown-menu-list-index-9tz3X1">
        <slot name="loadFailure">
          <ks-empty-state size="sm" title={t(commonMessages.loadFail)}>
            <div slot="illustration" class="load-fail-illustration"></div>
          </ks-empty-state>
        </slot>
      </div>
    );
  }

  private renderSearchResultTitle() {
    if (
      !this.hideSearchResultTitle &&
      this.filterOption instanceof Function &&
      this.searchValue &&
      this.filteredOptions?.length
    ) {
      return (
        <div key="search-result-title" class={`${this.prefixCls}__search-results-title`}>
          <ks-text variant="titleSm">{t(searchMessages.result)}</ks-text>
        </div>
      );
    }
  }

  render() {
    return (
      <Host class="KsDropdownMenuList">
        <ks-spinner loading={!!this.loading}>
          <div class={`${this.prefixCls}__wrapper`}>
            {this.listHeaderSlots && <slot name="listHeader" />}
            {this.renderSearchResultTitle()}
            {this.loadFailed
              ? this.renderLoadFail()
              : this.filteredOptions?.length
                ? this.renderList()
                : this.renderEmpty()}
            {this.filteredOptions && this.loadingMore && !this.loadFailed && (
              <div class={'loading-more'}>{this.loadMoreFailed ? <slot name="loadMoreFailure" /> : <ks-spinner />}</div>
            )}
          </div>
        </ks-spinner>
      </Host>
    );
  }

  /** @private Internal prop for render layer, please don't use. */
  @Prop() override wrapWithSlot: (slotName: string, children: unknown) => unknown = () => [];
  /** @private Internal prop for render layer, please don't use. */
  @Prop() override setDynamicRenderDeps: (children: unknown[], getPassThroughSlots?: () => VNode[]) => void = noop;

  ////// DEPS //////
  protected __DEPS__() {
    // istanbul ignore next
    return [<ks-checkbox />, <ks-tooltip />, <ks-text />];
  }
}
