import { Fragment, FunctionalComponent, h } from '@stencil/core';
import { DropdownItem } from '@src/components/ks-dropdown-menu-list/types';
import { KsMenuItemBase, MenuItemBaseProps } from './item';
import { mapVChildrenToSlots } from '@src/shared/vdom';

const prefix = 'dropdown-item';

export interface DropdownItemProps extends MenuItemBaseProps<DropdownItem> {
  groupTitle?: boolean;
  showDivider?: boolean;
}

export const KsDropdownItem: FunctionalComponent<DropdownItemProps> = (
  { groupTitle = false, showDivider = false, onClick, multiple, ...rest },
  children,
) => {
  const { label: labelSlots } = mapVChildrenToSlots(children, {}, false);
  const { disabled, checked, label } = rest;

  const labelUndefined = label === undefined && (!labelSlots || labelSlots.length === 0);
  const mergedMultiple = groupTitle ? false : multiple;
  const mergedActive = !mergedMultiple && checked;
  return (
    <Fragment>
      {showDivider && <div class={`${prefix}__divider`} />}
      {!(labelUndefined && groupTitle) && (
        <KsMenuItemBase<DropdownItem>
          classes={{
            [prefix]: true,
            [`${prefix}--group`]: groupTitle,
            [`${prefix}--active`]: checked,
            [`${prefix}--disabled`]: disabled || false,
            ...(rest.classes || {}),
          }}
          onClick={!groupTitle ? onClick : undefined}
          multiple={mergedMultiple}
          active={mergedActive}
          {...rest}
        >
          {children}
        </KsMenuItemBase>
      )}
    </Fragment>
  );
};
